const FATIHA=[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","Бисмилляахир-рахмаанир-рахиим"],[2,"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","Аль-хамду лиллаахи раббиль-‘ааламиин"],[3,"ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","Ар-рахмаанир-рахиим"],[4,"مَٰلِكِ يَوْمِ ٱلدِّينِ","Маалики йаумид-диин"],[5,"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","Иййаака на‘буду уа иййаака наста‘иин"],[6,"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","Ихдинас-сырааталь-мустақиим"],[7,"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","Сырааталь-лазиина ан‘амта ‘алейхим, гайриль-магдууби ‘алейхим уа лад-дааллиин"]];
const READINGS={1:FATIHA,112:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ هُوَ ٱللَّهُ أَحَدٌ","Бисмилляахир-рахмаанир-рахиим. Қуль хуал-лааху ахад"],[2,"ٱللَّهُ ٱلصَّمَدُ","Аллаахус-самад"],[3,"لَمْ يَلِدْ وَلَمْ يُولَدْ","Лям ялид уа лям юуляд"],[4,"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","Уа лям якул-ляху куфуан ахад"]],113:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","Бисмилляахир-рахмаанир-рахиим. Қуль а‘уузу би-раббиль-фаляқ"],[2,"مِن شَرِّ مَا خَلَقَ","Мин шарри маа халақ"],[3,"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","Уа мин шарри гаасиқин изаа уақаб"],[4,"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ","Уа мин шаррин-наффаасаати филь-‘уқад"],[5,"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","Уа мин шарри хаасидин изаа хасад"]],114:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","Бисмилляахир-рахмаанир-рахиим. Қуль а‘уузу би-раббин-наас"],[2,"مَلِكِ ٱلنَّاسِ","Маликин-наас"],[3,"إِلَٰهِ ٱلنَّاسِ","Иляахин-наас"],[4,"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","Мин шарриль-уасуаасиль-ханнаас"],[5,"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","Аллязии юуасуису фии судуурин-наас"],[6,"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","Миналь-джиннати уан-наас"]]};
const clean=t=>String(t).replace(/\ufeff/g,'');
export function hasOwnTranscription(surah){const rows=READINGS[surah?.number];return !!rows&&surah.verses?.length===rows.length&&surah.verses.every((v,i)=>v.ayah===rows[i][0]&&clean(v.arabic)===rows[i][1]);}
export function readingTranscription(surah,verse,edition){return edition==='salah-preview'&&hasOwnTranscription(surah)?READINGS[surah.number][verse.ayah-1][2]:verse.transliteration;}
export const ownTranscriptionNote='Пробная транскрипция SALAH · Аль-Фатиха, Аль-Ихлас, Аль-Фаляк и Ан-Нас. Составлена по арабскому тексту; проверка преподавателем ещё не выполнена. Две гласные обозначают удлинение, а не точное число счётов. К передаёт ك, қ — ق; знак ‘ обозначает ‘айн. Окончания аятов даны для остановки. Для точного произношения слушайте чтеца.';
